return [{
  json: {
    schema_version: '3.1',
    gcp_project: 'tmdatabase',
    bq_dataset: 'dm_base_crm',
    config_dataset: 'tmdatabase.dm_daily_brief',
    timezone: 'Asia/Ho_Chi_Minh',

    // Tat ca gia tri duoi day co the sua sau khi chay thu.
    thresholds: {
      trend_direction_pct: 10,
      warning_zero_lead_days: 5,
      min_base_volume: 3,
      cvr_direction_pp: 5,
      weekly_min_content_leads: 3,
      weekly_min_course_leads: 3,
      weekly_min_course_closed: 3,
      history_no_lead_days: 10,
      warning_open_deal_days: 14,
      warning_open_deal_min: 5,
      unmapped_alert_min: 3,
      unmapped_alert_rate_pct: 5,
    },

    limits: {
      daily_priority_limit: 3,
      weekly_priority_limit: 3,
      weekly_content_top_n: 5,
      weekly_content_query_rows: 100,
    },

    features: {
      enable_weekly_stale_open: false,
      show_daily_data_health_alert: true,
      show_weekly_data_health_alert: true,
    },

    openai_model: 'gpt-4.1',
  },
}];

function vnParts(date) {
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Ho_Chi_Minh',
    year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
  });
  const parts = formatter.formatToParts(date);
  const get = (type) => parts.find((part) => part.type === type)?.value || '';
  return { year: get('year'), month: get('month'), day: get('day'), weekday: get('weekday') };
}

function addDays(isoDate, days) {
  const date = new Date(isoDate + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function compactDate(isoDate) {
  return isoDate.slice(8, 10) + '/' + isoDate.slice(5, 7);
}

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    const value = Math.floor(Math.random() * 16);
    return (char === 'x' ? value : (value & 3) | 8).toString(16);
  });
}

const now = new Date();
const vn = vnParts(now);
const runDate = vn.year + '-' + vn.month + '-' + vn.day;
const weekdayMap = { Mon: 2, Tue: 3, Wed: 4, Thu: 5, Fri: 6, Sat: 7, Sun: 0 };
const reportDay = weekdayMap[vn.weekday];
const reportDate = addDays(runDate, -1);
const isSaturday = reportDay === 7;
const isSunday = reportDay === 0;

const weekdayLabels = {
  0: 'Chủ Nhật', 2: 'Thứ Hai', 3: 'Thứ Ba', 4: 'Thứ Tư',
  5: 'Thứ Năm', 6: 'Thứ Sáu', 7: 'Thứ Bảy',
};

const display = {
  2: { title: '📚 MARKETING ENTRY MONDAY', focus: 'MARKETING' },
  3: { title: '📣 MARKETING GROWTH TUESDAY', focus: 'MARKETING GROWTH' },
  4: { title: '🧠 EXECUTIVE WEDNESDAY', focus: 'EXECUTIVE' },
  5: { title: '📊 DATA THURSDAY', focus: 'DATA' },
  6: { title: '🤖 AI FRIDAY', focus: 'AI' },
};

const periods = {
  curr7_start: addDays(reportDate, -6), curr7_end: reportDate,
  prev7_start: addDays(reportDate, -13), prev7_end: addDays(reportDate, -7),
  prev30_start: addDays(reportDate, -36), prev30_end: addDays(reportDate, -7),
  prev90_start: addDays(reportDate, -96), prev90_end: addDays(reportDate, -7),
  week_curr_start: addDays(runDate, -5), week_curr_end: addDays(runDate, -1),
  week_prev_start: addDays(runDate, -12), week_prev_end: addDays(runDate, -8),
  trend_curr7_start: addDays(reportDate, -6), trend_curr7_end: reportDate,
};

return [{ json: {
  run_id: uuidv4(),
  run_date: runDate,
  run_date_display: compactDate(runDate),
  report_date: reportDate,
  report_date_display: compactDate(reportDate),
  report_day: reportDay,
  report_mode: isSunday ? 'sunday' : (isSaturday ? 'weekly' : 'daily'),
  is_saturday: isSaturday,
  is_sunday: isSunday,
  weekday_label: weekdayLabels[reportDay] || '',
  daily_display_title: display[reportDay]?.title || '',
  focus_group_label: display[reportDay]?.focus || '',
  week_label: compactDate(periods.week_curr_start) + '–' + compactDate(periods.week_curr_end),
  previous_week_label: compactDate(periods.week_prev_start) + '–' + compactDate(periods.week_prev_end),
  periods,
} }];

const rd = $('Resolve Calendar').first().json;
const text = String($json.output || $json.text || '').trim();
return [{ json: {
  run_id: rd.run_id,
  report_date: rd.report_date,
  sent_at: new Date().toISOString(),
  query_results: JSON.stringify({ schema_version: '3.1', report_mode: 'sunday', run_date: rd.run_date, report_date: rd.report_date }),
  agent_output: text,
  status: 'success',
  error_message: null,
} }];

function rows(name) {
  return $(name).all().map((item) => item.json);
}

function number(value, fallback = 0) {
  if (value === null || value === undefined || value === '') return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function bool(value) {
  return value === true || String(value).toLowerCase() === 'true';
}

function round(value, digits = 2) {
  const scale = 10 ** digits;
  return Math.round((number(value) + Number.EPSILON) * scale) / scale;
}

function pct(curr, prev) {
  if (number(prev) === 0) return null;
  return round(((number(curr) - number(prev)) / number(prev)) * 100, 1);
}

function direction(curr, baseline, history90, minVolume, thresholdPct) {
  const current = number(curr);
  const base = number(baseline);
  const lowVolume = (current * 7) < minVolume && number(history90) < minVolume;
  if (lowVolume) return 'flat';
  if (base === 0 && current === 0) return 'flat';
  if (base === 0 && current > 0) return 'up';
  if (current === 0 && base > 0) return 'down';
  const change = ((current - base) / base) * 100;
  if (change >= thresholdPct) return 'up';
  if (change <= -thresholdPct) return 'down';
  return 'flat';
}

function overallDirection(curr, prev, minVolume, thresholdPct) {
  const current = number(curr);
  const base = number(prev);
  if (current < minVolume && base < minVolume) return 'flat';
  if (base === 0 && current >= minVolume) return 'up';
  if (current === 0 && base >= minVolume) return 'down';
  return direction(current, base, Math.max(current, base), 0, thresholdPct);
}

function statusRank(status) {
  return { red: 4, orange: 3, yellow: 2, normal: 1 }[status] || 0;
}

function courseTrend(row, cfg, reportDate) {
  const minVolume = number(cfg.thresholds.min_base_volume);
  const trendPct = number(cfg.thresholds.trend_direction_pct);
  const lead = {
    curr7: number(row.lead_n_curr7), prev7: number(row.lead_n_prev7),
    prev30: number(row.lead_n_prev30), prev90: number(row.lead_n_prev90),
  };
  const won = {
    curr7: number(row.won_n_curr7), prev7: number(row.won_n_prev7),
    prev30: number(row.won_n_prev30), prev90: number(row.won_n_prev90),
  };
  const leadDirections = {
    prev7: direction(lead.curr7 / 7, lead.prev7 / 7, lead.prev90, minVolume, trendPct),
    prev30: direction(lead.curr7 / 7, lead.prev30 / 30, lead.prev90, minVolume, trendPct),
    prev90: direction(lead.curr7 / 7, lead.prev90 / 90, lead.prev90, minVolume, trendPct),
  };
