const rd = $('Resolve Calendar').first().json;
const q0 = rows('Q0 Daily Data Health');
const q1 = $('Q1 Daily Overall Funnel').first().json;
const q2 = rows('Q2 Daily Focus Trend');
const minVolume = number(cfg.thresholds.min_base_volume);
const trendPct = number(cfg.thresholds.trend_direction_pct);

function cvrDirection(changePp, currClosed, prevClosed) {
  if (number(currClosed) === 0 || number(prevClosed) === 0 || changePp === null || changePp === undefined) return 'flat';
  if (number(changePp) >= number(cfg.thresholds.cvr_direction_pp)) return 'up';
  if (number(changePp) <= -number(cfg.thresholds.cvr_direction_pp)) return 'down';
  return 'flat';
}

