  leads_avg7_curr: number(q1.leads_avg_curr), leads_avg7_prev: number(q1.leads_avg_prev), leads_pct_change: q1.leads_pct_change,
  mql_avg7_curr: number(q1.mql_avg_curr), mql_avg7_prev: number(q1.mql_avg_prev), mql_pct_change: q1.mql_pct_change,
  discovery_avg7_curr: number(q1.discovery_avg_curr), discovery_avg7_prev: number(q1.discovery_avg_prev), discovery_pct_change: q1.discovery_pct_change,
  needfit_avg7_curr: number(q1.needfit_avg_curr), needfit_avg7_prev: number(q1.needfit_avg_prev), needfit_pct_change: q1.needfit_pct_change,
  won_avg7_curr: number(q1.won_avg_curr), won_avg7_prev: number(q1.won_avg_prev), won_pct_change: q1.won_pct_change,
