overall.mql_direction = overallDirection(q1.mql_curr, q1.mql_prev, minVolume, trendPct);
overall.discovery_direction = overallDirection(q1.discovery_curr, q1.discovery_prev, minVolume, trendPct);
overall.needfit_direction = overallDirection(q1.needfit_curr, q1.needfit_prev, minVolume, trendPct);
overall.won_direction = overallDirection(q1.won_curr, q1.won_prev, minVolume, trendPct);
overall.cvr_direction = cvrDirection(q1.cvr_change_pp, number(q1.won_curr) + number(q1.lost_curr), number(q1.won_prev) + number(q1.lost_prev));

const acquisitionDown = overall.lead_direction === 'down' || overall.mql_direction === 'down';
const middleDown = overall.discovery_direction === 'down' || overall.needfit_direction === 'down';
const outcomeDown = overall.won_direction === 'down' || overall.cvr_direction === 'down';
const upLayers = [
  overall.lead_direction === 'up' || overall.mql_direction === 'up',
  overall.discovery_direction === 'up' || overall.needfit_direction === 'up',
  overall.won_direction === 'up' || overall.cvr_direction === 'up',
].filter(Boolean).length;

if (acquisitionDown && middleDown && outcomeDown) overall.summary_code = 'FUNNEL_BROAD_SLOWDOWN';
else if ((acquisitionDown || middleDown) && !outcomeDown) overall.summary_code = 'INPUT_MID_DOWN_OUTCOME_OK';
else if (!acquisitionDown && outcomeDown) overall.summary_code = 'OUTCOME_DOWN_INPUT_OK';
else if (!acquisitionDown && !middleDown && !outcomeDown && upLayers >= 2) overall.summary_code = 'FUNNEL_IMPROVING';
else overall.summary_code = 'FUNNEL_MIXED_OR_STABLE';

const focusCourses = q2.map((row) => courseTrend(row, cfg, rd.report_date));
focusCourses.sort((a, b) => statusRank(b.status) - statusRank(a.status) || a.course_name.localeCompare(b.course_name));

const candidates = focusCourses
  .filter((course) => course.status !== 'normal')
  .sort((a, b) => statusRank(b.status) - statusRank(a.status)
    || (b.lead_down_count + b.won_down_count) - (a.lead_down_count + a.won_down_count)
    || Number(b.flag_no_lead) - Number(a.flag_no_lead)
    || number(b.days_no_lead) - number(a.days_no_lead)
    || number(a.lead_change_prev7_pct, 999) - number(b.lead_change_prev7_pct, 999)
    || a.course_name.localeCompare(b.course_name));

const grouped = [];
for (const course of candidates) {
  const key = course.status + '|' + course.interpretation_code;
  let group = grouped.find((item) => item.key === key);
  if (!group) {
    group = { key, status: course.status, interpretation_code: course.interpretation_code, course_names: [], reason_codes: [] };
    grouped.push(group);
  }
  group.course_names.push(course.course_name);
  group.reason_codes = [...new Set([...group.reason_codes, ...course.status_reason])];
}

const priorityItems = grouped.slice(0, number(cfg.limits.daily_priority_limit)).map((item, index) => ({
  rank: index + 1,
  status: item.status,
  course_names: item.course_names,
  reason_codes: item.reason_codes,
  interpretation_code: item.interpretation_code,
}));

const totalLeads = number(q0[0]?.total_leads);
const missingCount = q0.filter((row) => row.mapping_status === 'MISSING_COURSE').reduce((sum, row) => sum + number(row.issue_count), 0);
const unmappedCount = q0.filter((row) => row.mapping_status === 'UNMAPPED_COURSE').reduce((sum, row) => sum + number(row.issue_count), 0);
const issueCount = missingCount + unmappedCount;
const issueRate = totalLeads ? round((issueCount / totalLeads) * 100, 1) : 0;
const dataSevere = issueCount >= number(cfg.thresholds.unmapped_alert_min)
  && issueRate >= number(cfg.thresholds.unmapped_alert_rate_pct);

return [{ json: {
  schema_version: cfg.schema_version,
  report_mode: 'daily',
  run_id: rd.run_id,
  run_date: rd.run_date,
  run_date_display: rd.run_date_display,
  report_date: rd.report_date,
  report_date_display: rd.report_date_display,
  report_day: rd.report_day,
  weekday_label: rd.weekday_label,
  daily_display_title: rd.daily_display_title,
  focus_group_label: rd.focus_group_label,
  periods: rd.periods,
  overall,
  focus_courses: focusCourses,
  priority_items: priorityItems,
  data_health: {
    total_leads: totalLeads,
    missing_course_count: missingCount,
    unmapped_course_count: unmappedCount,
    unmapped_rate_pct: issueRate,
    is_severe: dataSevere,
    alert_text_code: dataSevere ? 'COURSE_MAPPING_ISSUE' : null,
    rows: q0,
  },
  writer_rules: {
    priority_limit: number(cfg.limits.daily_priority_limit),
    show_data_health_alert: bool(cfg.features.show_daily_data_health_alert) && dataSevere,
  },
} }];

