  if (leadDownCount) reasons.push('LEAD_DOWN_' + leadDownCount + '_BASELINES');
  if (wonDownCount) reasons.push('WON_DOWN_' + wonDownCount + '_BASELINES');
  if (flagNoLead) reasons.push('NO_LEAD_' + daysNoLead + '_DAYS');

  return {
    course_key: row.course_key,
    course_name: row.course_name,
    course_type: row.course_type,
    lead_n_curr7: lead.curr7, lead_n_prev7: lead.prev7, lead_n_prev30: lead.prev30, lead_n_prev90: lead.prev90,
    lead_pd_curr7: round(lead.curr7 / 7), lead_pd_prev7: round(lead.prev7 / 7),
    lead_pd_prev30: round(lead.prev30 / 30), lead_pd_prev90: round(lead.prev90 / 90),
    lead_vs_prev7: leadDirections.prev7, lead_vs_prev30: leadDirections.prev30, lead_vs_prev90: leadDirections.prev90,
    won_n_curr7: won.curr7, won_n_prev7: won.prev7, won_n_prev30: won.prev30, won_n_prev90: won.prev90,
    won_pd_curr7: round(won.curr7 / 7), won_pd_prev7: round(won.prev7 / 7),
    won_pd_prev30: round(won.prev30 / 30), won_pd_prev90: round(won.prev90 / 90),
    won_vs_prev7: wonDirections.prev7, won_vs_prev30: wonDirections.prev30, won_vs_prev90: wonDirections.prev90,
    last_lead_date: row.last_lead_date || null,
    days_no_lead: daysNoLead,
    has_ever_had_lead: hasEverLead,
    baseline_lead_expected7: round((lead.prev90 / 90) * 7, 1),
    baseline_lead_expected5: round((lead.prev90 / 90) * 5, 1),
    is_low_volume: lowVolume,
    is_low_won_volume: lowWonVolume,
    flag_no_lead: flagNoLead,
    lead_down_count: leadDownCount,
    won_down_count: wonDownCount,
    status,
    status_reason: reasons,
    interpretation_code: interpretationCode,
    lead_change_prev7_pct: pct(lead.curr7, lead.prev7),
    won_change_prev7_pct: pct(won.curr7, won.prev7),
  };
}

const cfg = $('Config').first().json;
const rd = $('Resolve Calendar').first().json;
const q3 = $('Q3 Weekly Overall Funnel').first().json;
const q4 = rows('Q4 Weekly Course Performance');
const q5 = rows('Q5 Weekly Content Performance');
const q6 = rows('Q6 Weekly Data Health');
const minVolume = number(cfg.thresholds.min_base_volume);
const trendPct = number(cfg.thresholds.trend_direction_pct);

function weeklyOverallDirection(curr, prev) {
  return overallDirection(curr, prev, minVolume, trendPct);
}

const overall = {
  leads_curr: number(q3.leads_curr), leads_prev: number(q3.leads_prev), leads_pct_change: q3.leads_pct_change,
  mql_curr: number(q3.mql_curr), mql_prev: number(q3.mql_prev), mql_pct_change: q3.mql_pct_change,
  discovery_curr: number(q3.discovery_curr), discovery_prev: number(q3.discovery_prev), discovery_pct_change: q3.discovery_pct_change,
  needfit_curr: number(q3.needfit_curr), needfit_prev: number(q3.needfit_prev), needfit_pct_change: q3.needfit_pct_change,
  won_curr: number(q3.won_curr), won_prev: number(q3.won_prev), won_pct_change: q3.won_pct_change,
  lost_curr: number(q3.lost_curr), lost_prev: number(q3.lost_prev), lost_pct_change: q3.lost_pct_change,
  conversion_rate_curr: q3.cvr_curr, conversion_rate_prev: q3.cvr_prev, cvr_change_pp: q3.cvr_change_pp,
};

overall.lead_direction = weeklyOverallDirection(q3.leads_curr, q3.leads_prev);
overall.mql_direction = weeklyOverallDirection(q3.mql_curr, q3.mql_prev);
overall.discovery_direction = weeklyOverallDirection(q3.discovery_curr, q3.discovery_prev);
overall.needfit_direction = weeklyOverallDirection(q3.needfit_curr, q3.needfit_prev);
overall.won_direction = weeklyOverallDirection(q3.won_curr, q3.won_prev);
overall.lost_direction = weeklyOverallDirection(q3.lost_curr, q3.lost_prev);
overall.cvr_direction = number(q3.cvr_change_pp) >= number(cfg.thresholds.cvr_direction_pp) ? 'up'
  : (number(q3.cvr_change_pp) <= -number(cfg.thresholds.cvr_direction_pp) ? 'down' : 'flat');

const acquisitionDown = overall.lead_direction === 'down' || overall.mql_direction === 'down';
const middleDown = overall.discovery_direction === 'down' || overall.needfit_direction === 'down';
const outcomeDown = overall.won_direction === 'down' || overall.cvr_direction === 'down' || overall.lost_direction === 'up';
if (acquisitionDown && middleDown && outcomeDown) overall.summary_code = 'FUNNEL_BROAD_SLOWDOWN';
else if ((acquisitionDown || middleDown) && !outcomeDown) overall.summary_code = 'INPUT_MID_DOWN_OUTCOME_OK';
else if (!acquisitionDown && outcomeDown) overall.summary_code = 'OUTCOME_DOWN_INPUT_OK';
else overall.summary_code = 'FUNNEL_MIXED_OR_STABLE';

const courses = q4.map((row) => {
  const trend = courseTrend(row, cfg, rd.report_date);
  const stale = number(row.stale_open_deals);
  const staleFlag = bool(cfg.features.enable_weekly_stale_open)
    && stale >= number(cfg.thresholds.warning_open_deal_min);
  let weeklyStatus = trend.status;
  if (weeklyStatus === 'normal' && staleFlag) weeklyStatus = 'orange';
  return {
    ...trend,
    leads_this_week: number(row.leads_this_week),
    leads_last_week: number(row.leads_last_week),
    lead_week_pct_change: pct(row.leads_this_week, row.leads_last_week),
    won_this_week: number(row.won_this_week),
    won_last_week: number(row.won_last_week),
    won_week_pct_change: pct(row.won_this_week, row.won_last_week),
    lost_this_week: number(row.lost_this_week),
    lost_last_week: number(row.lost_last_week),
    closed_this_week: number(row.won_this_week) + number(row.lost_this_week),
    cvr_this_week: (number(row.won_this_week) + number(row.lost_this_week))
      ? round(number(row.won_this_week) / (number(row.won_this_week) + number(row.lost_this_week)) * 100, 1) : null,
    cvr_sample_ok: number(row.won_this_week) + number(row.lost_this_week) >= number(cfg.thresholds.weekly_min_course_closed),
    stale_open_deals: bool(cfg.features.enable_weekly_stale_open) ? stale : null,
    stale_open_flag: staleFlag,
    weekly_status: weeklyStatus,
    display_reason_codes: [
      ...trend.status_reason.filter((reason) => !reason.startsWith('NO_LEAD_')),
      ...(staleFlag ? ['WEEKLY_STALE_OPEN'] : []),
    ],
  };
});

function best(items, compare) {
  return items.length ? [...items].sort(compare)[0] : null;
}

const eligibleStrong = courses.filter((course) => course.leads_this_week >= number(cfg.thresholds.weekly_min_course_leads));
const eligibleChange = courses.filter((course) => course.leads_last_week >= minVolume && course.lead_week_pct_change !== null);
const strongest = best(eligibleStrong, (a, b) => b.won_this_week - a.won_this_week
  || number(b.cvr_sample_ok ? b.cvr_this_week : -1) - number(a.cvr_sample_ok ? a.cvr_this_week : -1)
  || b.leads_this_week - a.leads_this_week || a.course_name.localeCompare(b.course_name));
const improved = best(eligibleChange, (a, b) => b.lead_week_pct_change - a.lead_week_pct_change
  || (b.leads_this_week - b.leads_last_week) - (a.leads_this_week - a.leads_last_week)
  || (b.won_this_week - b.won_last_week) - (a.won_this_week - a.won_last_week)
  || a.course_name.localeCompare(b.course_name));
const declined = best(eligibleChange, (a, b) => a.lead_week_pct_change - b.lead_week_pct_change
  || (a.leads_this_week - a.leads_last_week) - (b.leads_this_week - b.leads_last_week)
  || (a.won_this_week - a.won_last_week) - (b.won_this_week - b.won_last_week)
  || a.course_name.localeCompare(b.course_name));
const weakest = best(eligibleStrong.filter((course) => course.leads_this_week > 0), (a, b) => a.won_this_week - b.won_this_week
  || number(a.cvr_sample_ok ? a.cvr_this_week : 999) - number(b.cvr_sample_ok ? b.cvr_this_week : 999)
  || number(a.lead_week_pct_change, 999) - number(b.lead_week_pct_change, 999)
  || a.course_name.localeCompare(b.course_name));

const historyThreshold = number(cfg.thresholds.history_no_lead_days);
const noLeadHistory = courses
  .filter((course) => !course.has_ever_had_lead || (course.days_no_lead !== null && course.days_no_lead > historyThreshold))
  .sort((a, b) => Number(a.has_ever_had_lead) - Number(b.has_ever_had_lead)
    || number(b.days_no_lead) - number(a.days_no_lead)
    || number(b.baseline_lead_expected7) - number(a.baseline_lead_expected7)
    || a.course_name.localeCompare(b.course_name));

const historyKeys = new Set(noLeadHistory.map((course) => course.course_key));
const newNoLeadWeekly = courses
  .filter((course) => course.leads_this_week === 0
    && course.has_ever_had_lead
    && !historyKeys.has(course.course_key)
    && (course.leads_last_week > 0 || course.baseline_lead_expected5 >= minVolume))
  .sort((a, b) => b.leads_last_week - a.leads_last_week
    || number(b.lead_pd_prev90) - number(a.lead_pd_prev90)
    || a.course_name.localeCompare(b.course_name));

const warnings = courses
  .filter((course) => course.display_reason_codes.length > 0 && (course.weekly_status !== 'normal' || course.stale_open_flag))
  .sort((a, b) => statusRank(b.weekly_status) - statusRank(a.weekly_status)
    || (b.lead_down_count + b.won_down_count) - (a.lead_down_count + a.won_down_count)
    || a.course_name.localeCompare(b.course_name));

const tracked = q5
  .filter((row) => !bool(row.is_untracked) && String(row.utm_content || '') !== '(not set)')
  .map((row) => ({
    ...row,
    cohort_cvr_pct: row.cohort_cvr_pct === null || row.cohort_cvr_pct === undefined
      ? null : number(row.cohort_cvr_pct),
  }));
const topByLeads = [...tracked].sort((a, b) => number(b.n_leads) - number(a.n_leads)
  || number(b.n_won) - number(a.n_won)
  || String(a.utm_content).localeCompare(String(b.utm_content)))
  .slice(0, number(cfg.limits.weekly_content_top_n));
const topByCvr = [...tracked]
  .filter((row) => number(row.n_leads) >= number(cfg.thresholds.weekly_min_content_leads)
    && number(row.n_closed) > 0 && row.cohort_cvr_pct !== null && row.cohort_cvr_pct !== undefined)
  .sort((a, b) => number(b.cohort_cvr_pct) - number(a.cohort_cvr_pct)
    || number(b.n_closed) - number(a.n_closed)
    || number(b.n_leads) - number(a.n_leads)
    || String(a.utm_content).localeCompare(String(b.utm_content)))
  .slice(0, number(cfg.limits.weekly_content_top_n));

const totalLeads = number(q6[0]?.total_leads);
const untrackedLeads = number(q6[0]?.untracked_leads);
const missingCount = q6.filter((row) => row.mapping_status === 'MISSING_COURSE').reduce((sum, row) => sum + number(row.issue_count), 0);
const unmappedCount = q6.filter((row) => row.mapping_status === 'UNMAPPED_COURSE').reduce((sum, row) => sum + number(row.issue_count), 0);
const issueCount = missingCount + unmappedCount;
const issueRate = totalLeads ? round(issueCount / totalLeads * 100, 1) : 0;
const dataSevere = issueCount >= number(cfg.thresholds.unmapped_alert_min)
  && issueRate >= number(cfg.thresholds.unmapped_alert_rate_pct);

const priorityItems = [];
const broadWarnings = warnings.filter((course) => course.lead_down_count > 0 && course.won_down_count > 0);
if (broadWarnings.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'COURSE_TREND_DOWN', course_names: broadWarnings.map((c) => c.course_name) });
if (newNoLeadWeekly.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'NEW_NO_LEAD_WEEKLY', course_names: newNoLeadWeekly.map((c) => c.course_name) });
if (noLeadHistory.length) priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'NO_LEAD_HISTORY', course_names: noLeadHistory.map((c) => c.course_name) });
if (bool(cfg.features.enable_weekly_stale_open) && warnings.some((course) => course.stale_open_flag)) {
  priorityItems.push({ rank: priorityItems.length + 1, priority_code: 'WEEKLY_STALE_OPEN', course_names: warnings.filter((c) => c.stale_open_flag).map((c) => c.course_name) });
}

return [{ json: {
  schema_version: cfg.schema_version,
  report_mode: 'weekly',
  run_id: rd.run_id,
  run_date: rd.run_date,
  report_date: rd.report_date,
  report_date_display: rd.report_date_display,
  week_label: rd.week_label,
  previous_week_label: rd.previous_week_label,
  periods: rd.periods,
  overall,
  course_leaderboard: {
    strongest: { eligible: Boolean(strongest), course: strongest, reason_codes: strongest ? ['WON_DESC', 'CVR_SAMPLE_GATED'] : [] },
    most_improved: { eligible: Boolean(improved), course: improved, reason_codes: improved ? ['LEAD_CHANGE_DESC'] : [] },
    most_declined: { eligible: Boolean(declined), course: declined, reason_codes: declined ? ['LEAD_CHANGE_ASC'] : [] },
    weakest: { eligible: Boolean(weakest), course: weakest, reason_codes: weakest ? ['WON_ASC', 'CVR_SAMPLE_GATED'] : [] },
  },
  content_performance: {
    top_by_leads: topByLeads,
    top_by_cvr: topByCvr,
    untracked: { n_leads: untrackedLeads, share_pct: totalLeads ? round(untrackedLeads / totalLeads * 100, 1) : 0 },
    cvr_label: 'CVR cohort hiện tại',
  },
  warnings: { total: warnings.length, courses: warnings, display_courses: warnings },
  no_lead_history: { threshold_days: historyThreshold, total: noLeadHistory.length, courses: noLeadHistory, display_courses: noLeadHistory },
  new_no_lead_weekly: { total: newNoLeadWeekly.length, courses: newNoLeadWeekly },
  priority_items: priorityItems.slice(0, number(cfg.limits.weekly_priority_limit)),
  data_health: {
    total_leads: totalLeads,
    missing_course_count: missingCount,
    unmapped_course_count: unmappedCount,
    unmapped_rate_pct: issueRate,
    untracked_utm_count: untrackedLeads,
    is_severe: dataSevere,
    alert_text_code: dataSevere ? 'COURSE_MAPPING_ISSUE' : null,
    rows: q6,
  },
  writer_rules: {
    priority_limit: number(cfg.limits.weekly_priority_limit),
    show_data_health_alert: bool(cfg.features.show_weekly_data_health_alert) && dataSevere,
    show_weekly_stale_open: bool(cfg.features.enable_weekly_stale_open),
  },
} }];

